{
  "routing_plan": [
    {
      "step": 1,
      "decision": "orchestrator-direct",
      "task_type_or_null": null,
      "reasoning": "Perform the bounded registration edits directly, including the three known icon references and the package contribution changes. Run Layer 2 and a targeted host check afterward. Retaking or retiring the stale screenshot is an operator approval decision, not a reason to consume a routed model call."
    },
    {
      "step": 2,
      "decision": "ROUTED through route()",
      "task_type_or_null": "architecture",
      "reasoning": "Making the native view the shipping view is an architectural switchover, not merely deletion. Route one DABBLER API-key call to review view identity, contribution order, preserved model consumers, and the no-early-deletion constraint. Include the manifestFaults-to-TreeView.message fix and require the Playwright verdict wording to say the glyph pair is selected, not required. The orchestrator should execute the approved bounded changes."
    },
    {
      "step": 3,
      "decision": "ROUTED through route()",
      "task_type_or_null": "architecture",
      "reasoning": "The stacked WebviewView, viewsWelcome empty state, transient TreeView.message behavior, lifecycle, and cross-view layout need architectural reasoning. Route this through the DABBLER budget, with explicit acceptance checks for the Getting Started form, System Status strip, empty state, fault message, and absence of an overlay over the first tree row."
    },
    {
      "step": 4,
      "decision": "ROUTED through route()",
      "task_type_or_null": "test-generation",
      "reasoning": "Test generation is explicitly required to be routed. Supply the complete old suite, its behavioral intent, the native tree public surface, and the S2 model/API details. Require re-expression of expansion, lazy children, stable identity, menus, empty state, manifest faults, and real click behavior rather than DOM equivalence. Run the required remediation checks against the pre-fix state and fixed state and record both results."
    },
    {
      "step": 5,
      "decision": "ROUTED through route()",
      "task_type_or_null": "code-review",
      "reasoning": "The actual removal is mechanical, but deciding whether it is safe to remove CustomSessionSetsView.ts, client.js, tree.css, the ellipsis rule, action strip, and RowPayload fields requires an import/consumer review. Route one deletion-diff review through DABBLER, then perform the approved removals directly. The review must explicitly confirm that moduleAssembly.ts, orderedBuckets, and every tree-model helper remain reachable."
    },
    {
      "step": 6,
      "decision": "ROUTED through route()",
      "task_type_or_null": "session-verification",
      "reasoning": "Run the FULL Layer 3 suite exactly once, at the session close, after all code and asset changes. The routed verification must include the new native view, expansion, lazy loading, menus, empty state, stacked surfaces, and the manifest-fault message. No code changes may follow this run."
    },
    {
      "step": 7,
      "decision": "ROUTED through route()",
      "task_type_or_null": "session-verification",
      "reasoning": "Use a final routed verification pass to inspect the full-run evidence, Layer 2 results, deletion/orphan checks, progress keys, and the three icon references. The operator must make the final close decision and record closure; the routed call must not trigger another FULL Layer 3 run."
    }
  ],
  "test_rewrite_verdict": "Worth routing through the DABBLER API-key budget. The rewrite is large, is explicitly test generation, and benefits from an independent behavioral mapping of the old suite. The orchestrator should still retain the whole old suite and provide the behavioral context so the routed call does not invent requirements from a summary. Review the generated tests for public-surface assertions, real clicks, lazy-child transitions, the malformed-modules.yaml fault path, and correction of the glyph verdict from required to selected.",
  "riskiest_thing": {
    "risk": "A migration can pass Layer 2 and static checks while the real workbench is interaction-blocking: a hover-revealed action strip or transparent layer can retain flow height or pointer hit area above the first native tree row and swallow expansion clicks. The stacked WebviewView also creates a plausible location for this class of regression.",
    "cheapest_control": "Add one targeted Layer 3 interaction test that performs a normal, non-forced click on the first module tree item and asserts that a lazy child appears. Before deleting the old renderer, apply one temporary production-equivalent overlay regression, run the targeted test, require it to fail, remove the regression, and require the same test to pass. Record both outputs.",
    "what_to_seed": "Temporarily force the action-strip or equivalent overlay to render without hover, give it nonzero height, position it at the top of the tree area with a higher stacking order, and leave pointer-events enabled so it covers the first row. If the WebviewView sandbox cannot cross the native-tree boundary, inject the equivalent overlay into the real workbench frame in Playwright. The test must open the normal container, click the actual accessible tree item, and assert the status bucket or session child; it must not use force-click or presence-only assertions."
  },
  "sequencing_gap": {
    "failure_mode_not_covered": "Green tests written before the switchover can explicitly open the contributed native view while production still selects or displays the old WebviewView. They therefore do not prove the final contribution order, normal-container entry point, stacked layout, old-view removal, or absence of an overlay after deletion. A valid-manifest-only suite can also miss the known fail-quiet manifestFaults path.",
    "what_to_add": "After the final package switch, deletion, and re-homing, run a targeted clean-host smoke test before the one final FULL Layer 3 run. It must open the normal container, assert that the native TreeView is the shipping view and the old renderer is absent, verify the stacked WebviewView does not cover the first row, click and expand that row, and exercise malformed modules.yaml so TreeView.message becomes explanatory and clears on valid data. Follow this with the mandated single FULL Layer 3 run and make no further changes."
  },
  "deletion_granularity": {
    "verdict": "Keep the switchover and re-homing in the same session, but stage them as separate verified phases rather than one atomic deletion.",
    "reasoning": "There is no S5, and deferring either the native switchover or the non-tree-surface migration to S4 would push architectural integration risk into the release session. First write and green the new suites, seed and catch the interaction regression, then delete the old renderer and its CSS and remove only proven-orphaned code. Immediately activate the new stacked WebviewView and viewsWelcome/TreeView.message behavior, run targeted checks, and reserve the single FULL Layer 3 run for the end. This avoids a dual-view release without risking accidental loss of Getting Started or System Status."
  },
  "next_orchestrator": {
    "engine": "claude",
    "provider": "anthropic",
    "model": "claude-opus-5",
    "effort": "high",
    "reasoning": "S4 is the release session, includes UAT, must walk the completed Explorer, and carries the final full-strength Playwright and advisory path-aware critique. Claude Opus at high effort has already produced the strongest demonstrated continuity on this set, while the prior status-SVG recommendation shows that confident API recall must be checked in a real host rather than trusted. Use focused routed verification and measurement, not additional ceremony or repeated full runs.",
    "budget_source": "DABBLER_* API-key routed budget, not the limited Copilot seat and not a competing engine CLI."
  },
  "next_session_set": {
    "recommendation": "Run the owed adopt-dabbler.md walk next, with the small router model-ID fix as an immediate prerequisite.",
    "reasoning": "The adoption walk is currently the number-one unpaid item and has never been executed, so the repository lacks evidence about whether the orchestration machinery is worth retaining. Make it a minimal, executable, measurement-based walk rather than another ceremonial round. Fixing the router's non-existent model IDs first prevents invalid routing and wasted budget. After the walk, use its findings to shape candidate Set 111's capability-scaling test; defer the unrelated Java track until that decision is made."
  },
  "confidence_notes": "The recommendations about S2's real-host baseline, the native model boundaries, the two residuals, the icon references, and the operator ordering are directly supported by the supplied evidence. I am recalling VS Code API behavior rather than deriving it fully from the evidence when describing TreeView.message as a transient message channel, contributes.viewsWelcome as the empty-view mechanism, and workbench contribution ordering/visibility as the determinant of the normal displayed view; those assumptions should be confirmed in the Extension Development Host. The exact pointer-event boundary between a WebviewView and a native TreeView is also not established here, so the overlay control must be validated by real-host Playwright rather than API-memory or static reasoning. I am explicitly not relying on the earlier currentColor recommendation because the S2 host measurement disproved it."
}
